/**
 * One-shot rig. Prints the CHAR_PX table for the phone header's face and size, so labels.ts can be
 * regenerated by measurement rather than by hand. Not run in CI — it needs a browser, and the
 * table it produces is a committed constant (docs/app.md §Columns and sorting).
 *
 * Run from the repo root: node app/scripts/measure-label-widths.mjs
 */
import { chromium } from 'playwright';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const woff = join(here, '../src/assets/fonts/inter-tight.woff2');
const b64 = readFileSync(woff).toString('base64');

const CHARS = [...'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,/()%-Δ'];

const browser = await chromium.launch();
const page = await browser.newPage();
await page.setContent('<body></body>');
const out = await page.evaluate(async ({ b64, chars }) => {
  const face = new FontFace('M', `url(data:font/woff2;base64,${b64}) format('woff2-variations')`,
    { weight: '400 700' });
  await face.load();
  document.fonts.add(face);
  const s = document.createElement('span');
  // Exactly the phone header's spec: 12px, weight 600, -0.02em tracking.
  //
  // `M, system-ui`, not `M` alone: the shipped file is the LATIN subset, and `Δ` (U+0394) is not
  // in it — the subset stops at the Latin block plus a short punctuation tail. The browser falls
  // back per glyph, so `Δ` is measured against whatever comes next in the stack, and the stack
  // here must therefore be the app's own (`--font-ui` is `'Inter Tight', system-ui, sans-serif`)
  // rather than the headless default. Two SHORT_LABELS depend on it: `Cold softness Δ` and
  // `Cold stiffness Δ`.
  s.style.cssText = 'position:absolute;white-space:pre;font-family:M,system-ui;font-size:12px;font-weight:600;letter-spacing:-0.02em';
  document.body.appendChild(s);
  const table = {};
  for (const ch of chars) {
    // 20 repeats then divide: a single glyph rounds badly at this size.
    s.textContent = ch.repeat(20);
    table[ch] = +(s.getBoundingClientRect().width / 20).toFixed(2);
  }
  // FALLBACK_PX stands in for a character the table has never seen, so it must be at least the
  // widest thing measured rather than a leftover from the previous face.
  return { table, fallback: Math.ceil(Math.max(...Object.values(table))) };
}, { b64, chars: CHARS });

console.log(JSON.stringify(out.table, null, 0));
console.log('FALLBACK_PX =', out.fallback);
await browser.close();
